    if (d1 < 0) d1 = 0; if (d2 < 0) d2 = 0; if (d3 < 0) d3 = 0; if (d4 < 0) d4 = 0; if (d5 < 0) d5 = 0;
    long total = (long)blorp_checked_mul(blorp_checked_mul(d1, blorp_checked_mul(d2, d3)), blorp_checked_mul(d4, d5));
