    blorp_Vector* arr = (blorp_Vector*)blorp_alloc(blorp_checked_add(sizeof(blorp_Vector), blorp_checked_mul(size, sizeof(void*))));
    BLORP_TAG(arr, "Vector");
    arr->len = size;
    arr->capacity = size;  /* Fixed size for arrays */
    arr->elem_release = NULL;
    arr->elem_size = 8;
