blorp_WebSocketVoidResult blorp_websocket_send_close_raw(
    blorp_WebSocketSession* session,
    long code,
    blorp_String* reason
) {
    const blorp_WebSocketBackendOps* backend = NULL;
    blorp_WebSocketVoidResult error_result;
    if (!blorp_websocket_ready_for_close_send(
            session, &backend, &error_result)) {
        return error_result;
    }
    blorp_WebSocketVoidResult validation =
        blorp_websocket_validate_close_args(code, reason);
    if (validation.error_kind != BLORP_WEBSOCKET_ERROR_NONE) {
        return validation;
    }
    if (validation.detail) blorp_release(validation.detail);
    if (!blorp_websocket_backend_supports(
            backend,
            BLORP_WEBSOCKET_BACKEND_CAP_SEND_CONTROL)) {
        return blorp_websocket_void_result_error(
            BLORP_WEBSOCKET_ERROR_UNSUPPORTED,
            "WebSocket backend does not support control sends");
    }
    blorp_WebSocketOperationCleanup op_cleanup;
    blorp_CancelCleanupFrame cleanup_frame;
    if (!blorp_websocket_begin_write_cleanup(
            session, &op_cleanup, &cleanup_frame, &error_result)) {
        return error_result;
    }
    blorp_WebSocketVoidResult result =
        backend->send_close(session, code, reason);
    if (result.error_kind == BLORP_WEBSOCKET_ERROR_NONE) {
        session->state = BLORP_WEBSOCKET_SESSION_CLOSING;
    }
    blorp_websocket_operation_cleanup_end(&op_cleanup);
    blorp_websocket_operation_cleanup_pop(&op_cleanup);
    return result;
}

// ============================================================================
// UDP Networking
// ============================================================================

static bool blorp_udp_payload_is_valid(const blorp_Bytes* data) {
    return data && data->len >= 0 && data->capacity >= 0 &&
           data->len <= data->capacity;
}

static blorp_UdpErrorKind blorp_udp_error_kind_from_errno(int errnum) {
    if (errnum == EINTR) return BLORP_UDP_ERROR_INTERRUPTED;
    if (errnum == EAGAIN) return BLORP_UDP_ERROR_BUSY;
#if defined(EWOULDBLOCK) && EWOULDBLOCK != EAGAIN
    if (errnum == EWOULDBLOCK) return BLORP_UDP_ERROR_BUSY;
#endif
    if (errnum == ETIMEDOUT) return BLORP_UDP_ERROR_TIMED_OUT;
    if (errnum == EBADF || errnum == ENOTSOCK) return BLORP_UDP_ERROR_CLOSED;
    if (errnum == EINVAL || errnum == EDESTADDRREQ || errnum == EMSGSIZE) {
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
#if defined(EAFNOSUPPORT)
    if (errnum == EAFNOSUPPORT) return BLORP_UDP_ERROR_UNSUPPORTED;
#endif
#if defined(EPROTONOSUPPORT)
    if (errnum == EPROTONOSUPPORT) return BLORP_UDP_ERROR_UNSUPPORTED;
#endif
#if defined(EOPNOTSUPP)
    if (errnum == EOPNOTSUPP) return BLORP_UDP_ERROR_UNSUPPORTED;
#endif
#if defined(ENOPROTOOPT)
    if (errnum == ENOPROTOOPT) return BLORP_UDP_ERROR_UNSUPPORTED;
#endif
    return BLORP_UDP_ERROR_OTHER;
}

static blorp_String* blorp_udp_errno_detail(const char* operation, int errnum) {
    char buf[256];
    snprintf(buf, sizeof(buf), "%s: %s", operation, strerror(errnum));
    return blorp_string_from_buf(buf, (long)strlen(buf));
}

static blorp_UdpSocketResult blorp_udp_socket_error(
    blorp_UdpErrorKind kind,
    blorp_String* detail
) {
    return (blorp_UdpSocketResult){
        .handle = NULL,
        .error_kind = kind,
        .detail = detail
    };
}

static blorp_UdpSocketResult blorp_udp_socket_ok(blorp_UdpSocket* socket) {
    return (blorp_UdpSocketResult){
        .handle = socket,
        .error_kind = BLORP_UDP_ERROR_NONE,
        .detail = NULL
    };
}

static blorp_UdpVoidResult blorp_udp_void_error(
    blorp_UdpErrorKind kind,
    blorp_String* detail
) {
    return (blorp_UdpVoidResult){ .error_kind = kind, .detail = detail };
}

static blorp_UdpVoidResult blorp_udp_void_ok(void) {
    return (blorp_UdpVoidResult){
        .error_kind = BLORP_UDP_ERROR_NONE,
        .detail = NULL
    };
}

static blorp_UdpIntResult blorp_udp_int_error(
    blorp_UdpErrorKind kind,
    blorp_String* detail
) {
    return (blorp_UdpIntResult){
        .value = 0,
        .error_kind = kind,
        .detail = detail
    };
}

static blorp_UdpIntResult blorp_udp_int_ok(long value) {
    return (blorp_UdpIntResult){
        .value = value,
        .error_kind = BLORP_UDP_ERROR_NONE,
        .detail = NULL
    };
}

static blorp_UdpDatagramResult blorp_udp_datagram_error(
    blorp_UdpErrorKind kind,
    blorp_String* detail
) {
    return (blorp_UdpDatagramResult){
        .data = NULL,
        .host = NULL,
        .port = 0,
        .error_kind = kind,
        .detail = detail
    };
}

static blorp_UdpDatagramResult blorp_udp_datagram_ok(
    blorp_Bytes* data,
    blorp_String* host,
    long port
) {
    return (blorp_UdpDatagramResult){
        .data = data,
        .host = host,
        .port = port,
        .error_kind = BLORP_UDP_ERROR_NONE,
        .detail = NULL
    };
}

static blorp_IoWaiter** blorp_udp_socket_waiter_slot(
    blorp_UdpSocket* socket,
    blorp_IoWaitKind kind
) {
    if (!socket) return NULL;
    switch (kind) {
        case BLORP_IO_WAIT_READ:
            return &socket->read_waiter;
        case BLORP_IO_WAIT_WRITE:
            return &socket->write_waiter;
        case BLORP_IO_WAIT_NONE:
        case BLORP_IO_WAIT_ACCEPT:
        case BLORP_IO_WAIT_CONNECT:
        default:
            return NULL;
    }
}

static blorp_IoInstallWaiterResult blorp_udp_socket_install_waiter(
    blorp_UdpSocket* socket,
    blorp_IoWaiter* waiter
) {
    if (!socket || !waiter || waiter->installed ||
        waiter->wake_reason != BLORP_IO_WAKE_NONE) {
        return BLORP_IO_INSTALL_WAITER_INVALID;
    }

    pthread_mutex_lock(&socket->mutex);
    blorp_IoWaiter** slot =
        blorp_udp_socket_waiter_slot(socket, waiter->kind);
    if (!slot || socket->state != BLORP_UDP_STATE_OPEN || socket->fd < 0 ||
        waiter->generation != socket->generation) {
        pthread_mutex_unlock(&socket->mutex);
        return BLORP_IO_INSTALL_WAITER_CLOSED;
    }
    if (*slot) {
        pthread_mutex_unlock(&socket->mutex);
        return BLORP_IO_INSTALL_WAITER_BUSY;
    }
    *slot = waiter;
    blorp_io_waiter_shared_retain(waiter);
    waiter->installed = true;
    waiter->installed_owner = blorp_io_wait_owner_udp(socket);
    waiter->next = NULL;
    pthread_mutex_unlock(&socket->mutex);
    return BLORP_IO_INSTALL_WAITER_OK;
}

static int blorp_udp_socket_remove_waiter(
    blorp_UdpSocket* socket,
    blorp_IoWaiter* waiter
) {
    if (!socket || !waiter) return 0;
    pthread_mutex_lock(&socket->mutex);
    blorp_IoWaiter** slot =
        blorp_udp_socket_waiter_slot(socket, waiter->kind);
    if (!slot || *slot != waiter) {
        pthread_mutex_unlock(&socket->mutex);
        return 0;
    }
    *slot = NULL;
    waiter->installed = false;
    waiter->installed_owner = blorp_io_wait_owner_none();
    waiter->next = NULL;
    pthread_mutex_unlock(&socket->mutex);
    blorp_io_deadline_queue_remove(waiter);
    blorp_io_waiter_shared_release(waiter);
    return 1;
}

static void blorp_udp_socket_extract_waiter_slot_locked(
    blorp_IoWaiter** slot,
    blorp_IoWakeReason reason,
    blorp_IoWaiterList* waiters
) {
    if (!slot || !*slot) return;
    blorp_IoWaiter* waiter = *slot;
    *slot = NULL;
    waiter->installed = false;
    waiter->installed_owner = blorp_io_wait_owner_none();
    waiter->wake_reason = reason;
    if (reason == BLORP_IO_WAKE_CANCELLED) waiter->cancelled = true;
    blorp_io_deadline_queue_remove(waiter);
    blorp_io_waiter_list_push_owned(waiters, waiter);
}

static blorp_IoWaiterList blorp_udp_socket_extract_waiter(
    blorp_UdpSocket* socket,
    blorp_IoWaitKind kind,
    uint64_t generation,
    blorp_IoWakeReason reason
) {
    blorp_IoWaiterList waiters = blorp_io_waiter_list_empty();
    if (!socket || reason == BLORP_IO_WAKE_NONE) return waiters;
    pthread_mutex_lock(&socket->mutex);
    blorp_IoWaiter** slot = blorp_udp_socket_waiter_slot(socket, kind);
    if (slot && *slot && socket->generation == generation &&
        (*slot)->generation == generation) {
        blorp_udp_socket_extract_waiter_slot_locked(slot, reason, &waiters);
    }
    pthread_mutex_unlock(&socket->mutex);
    return waiters;
}

static blorp_IoWaiterList blorp_udp_socket_extract_exact_waiter(
    blorp_UdpSocket* socket,
    blorp_IoWaiter* waiter,
    blorp_IoWakeReason reason
) {
    blorp_IoWaiterList waiters = blorp_io_waiter_list_empty();
    if (!socket || !waiter || reason == BLORP_IO_WAKE_NONE) return waiters;
    pthread_mutex_lock(&socket->mutex);
    blorp_IoWaiter** slot =
        blorp_udp_socket_waiter_slot(socket, waiter->kind);
    if (slot && blorp_io_waiter_same_operation(*slot, waiter)) {
        blorp_udp_socket_extract_waiter_slot_locked(slot, reason, &waiters);
    }
    pthread_mutex_unlock(&socket->mutex);
    return waiters;
}

static int blorp_udp_socket_cancel_waiter(
    blorp_UdpSocket* socket,
    blorp_IoWaiter* waiter
) {
    if (!socket || !waiter) return 0;
    blorp_IoWaiterList waiters =
        blorp_udp_socket_extract_exact_waiter(
            socket, waiter, BLORP_IO_WAKE_CANCELLED);
    int cancelled = waiters.head != NULL;
    blorp_io_waiter_wake_all(&waiters);
    return cancelled;
}

static blorp_IoWaiterList blorp_udp_socket_close_and_extract_waiters(
    blorp_UdpSocket* socket,
    blorp_IoWakeReason reason,
    int* closed_fd_out,
    uint64_t* closed_generation_out
) {
    blorp_IoWaiterList waiters = blorp_io_waiter_list_empty();
    if (closed_fd_out) *closed_fd_out = -1;
    if (closed_generation_out) *closed_generation_out = 0;
    if (!socket) return waiters;

    pthread_mutex_lock(&socket->mutex);
    if (socket->state != BLORP_UDP_STATE_CLOSED) {
        socket->state = BLORP_UDP_STATE_CLOSED;
        if (socket->fd >= 0) {
            if (closed_fd_out) *closed_fd_out = socket->fd;
            if (closed_generation_out) *closed_generation_out = socket->generation;
            close(socket->fd);
            socket->fd = -1;
        }
    }
    blorp_udp_socket_extract_waiter_slot_locked(
        &socket->read_waiter, reason, &waiters);
    blorp_udp_socket_extract_waiter_slot_locked(
        &socket->write_waiter, reason, &waiters);
    pthread_mutex_unlock(&socket->mutex);
    return waiters;
}

static void blorp_udp_socket_retain(blorp_UdpSocket* socket) {
    if (socket) {
        atomic_fetch_add_explicit(&socket->refcount, 1, memory_order_relaxed);
    }
}

static void blorp_udp_socket_release(blorp_UdpSocket* socket) {
    if (!socket) return;
    long old_refcount =
        atomic_fetch_sub_explicit(&socket->refcount, 1, memory_order_acq_rel);
    if (old_refcount > 1) return;

    blorp_IoWaiterList waiters =
        blorp_udp_socket_close_and_extract_waiters(
            socket, BLORP_IO_WAKE_CLOSED, NULL, NULL);
    if (waiters.head) {
        fprintf(stderr, "blorp: UDP socket destroyed with waiting fiber (bug)\n");
    }
    blorp_io_waiter_wake_all(&waiters);
    pthread_mutex_destroy(&socket->mutex);
    free(socket);
}

static void blorp_udp_socket_cleanup_release(void* value) {
    blorp_udp_socket_release((blorp_UdpSocket*)value);
}

static void blorp_udp_socket_operation_cleanup_push(
    blorp_CancelCleanupFrame* frame,
    blorp_UdpSocket** slot,
    blorp_UdpSocket* socket
) {
#if defined(__clang_analyzer__)
    (void)frame;
    (void)slot;
    (void)socket;
#else
    __blorp_task_cleanup_push_slow(
        frame, slot, socket, blorp_udp_socket_cleanup_release);
#endif
}

static void blorp_udp_socket_operation_cleanup_pop(blorp_UdpSocket** slot) {
#if defined(__clang_analyzer__)
    (void)slot;
#else
    __blorp_task_cleanup_pop_slot_slow(slot);
#endif
}

static int blorp_udp_socket_begin_op(
    blorp_UdpSocket* socket,
    long* fd_out,
    uint64_t* generation_out,
    long* timeout_ms_out
) {
    if (!socket || !fd_out) return -1;
    pthread_mutex_lock(&socket->mutex);
    if (socket->state != BLORP_UDP_STATE_OPEN || socket->fd < 0) {
        pthread_mutex_unlock(&socket->mutex);
        return -1;
    }
    *fd_out = socket->fd;
    if (generation_out) *generation_out = socket->generation;
    if (timeout_ms_out) *timeout_ms_out = socket->default_timeout_ms;
    return 0;
}

static void blorp_udp_socket_end_op(blorp_UdpSocket* socket) {
    if (socket) pthread_mutex_unlock(&socket->mutex);
}

static bool blorp_udp_host_is_numeric(const char* host, int family) {
    if (!host || host[0] == '\0') return false;

    struct in_addr addr4;
    if ((family == AF_INET || family == AF_UNSPEC) &&
        inet_pton(AF_INET, host, &addr4) == 1) {
        return true;
    }

    struct in6_addr addr6;
    if ((family == AF_INET6 || family == AF_UNSPEC) &&
        inet_pton(AF_INET6, host, &addr6) == 1) {
        return true;
    }

    return false;
}

static blorp_UdpErrorKind blorp_udp_copy_host(
    const char* operation,
    const blorp_String* host,
    char* host_buf,
    size_t host_buf_len,
    blorp_String** detail_out
) {
    if (detail_out) *detail_out = NULL;
    if (!operation || !host_buf || host_buf_len == 0 || !detail_out) {
        if (detail_out) *detail_out = blorp_string_create("udp: invalid host");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    if (!host) {
        *detail_out = blorp_string_create("host must not be null");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    if (host->len < 0 || host->capacity < 0 || host->len > host->capacity) {
        *detail_out = blorp_string_create("host has invalid length");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    if ((size_t)host->len >= host_buf_len) {
        *detail_out = blorp_string_create("host must be shorter than 256 bytes");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    if (memchr(host->data, '\0', (size_t)host->len) != NULL) {
        *detail_out = blorp_string_create("host contains NUL byte");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    (void)operation;
    memcpy(host_buf, host->data, (size_t)host->len);
    host_buf[host->len] = '\0';
    return BLORP_UDP_ERROR_NONE;
}

static int blorp_udp_getaddrinfo(
    const char* host,
    const char* port,
    struct addrinfo* hints,
    struct addrinfo** res
) {
    const char* lookup_host = host;
    if (host && host[0] == '\0' && hints && (hints->ai_flags & AI_PASSIVE)) {
        lookup_host = NULL;
    }

    struct addrinfo numeric_hints;
    if (lookup_host &&
        blorp_udp_host_is_numeric(lookup_host, hints ? hints->ai_family : AF_UNSPEC)) {
        numeric_hints = hints ? *hints : (struct addrinfo){0};
        hints = &numeric_hints;
        hints->ai_flags |= AI_NUMERICHOST;
    }
    return getaddrinfo(lookup_host, port, hints, res);
}

static blorp_UdpErrorKind blorp_udp_resolve_addr(
    const char* operation,
    const blorp_String* host,
    long port,
    bool passive,
    bool numeric_only,
    struct addrinfo** out,
    blorp_String** detail_out
) {
    if (out) *out = NULL;
    if (detail_out) *detail_out = NULL;
    if (!out || !detail_out) {
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    if (port < 0 || port > 65535) {
        *detail_out = blorp_string_create("port must be between 0 and 65535");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }

    char host_buf[256];
    blorp_UdpErrorKind host_kind =
        blorp_udp_copy_host(operation, host, host_buf, sizeof(host_buf), detail_out);
    if (host_kind != BLORP_UDP_ERROR_NONE) return host_kind;
    if (numeric_only) {
        if (host_buf[0] == '\0') {
            if (!passive) {
                *detail_out =
                    blorp_string_create("host must be a numeric IPv4 address");
                return BLORP_UDP_ERROR_INVALID_INPUT;
            }
        } else if (!blorp_udp_host_is_numeric(host_buf, AF_INET)) {
            *detail_out = blorp_string_create(
                passive
                    ? "host must be a numeric IPv4 address or empty bind-any host"
                    : "host must be a numeric IPv4 address");
            return BLORP_UDP_ERROR_INVALID_INPUT;
        }
    }

    char port_buf[8];
    snprintf(port_buf, sizeof(port_buf), "%ld", port);

    struct addrinfo hints = {0};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    if (passive) hints.ai_flags = AI_PASSIVE;
    if (numeric_only && host_buf[0] != '\0') hints.ai_flags |= AI_NUMERICHOST;

    int rc = blorp_udp_getaddrinfo(host_buf, port_buf, &hints, out);
    if (rc != 0) {
        char err_buf[256];
        snprintf(
            err_buf,
            sizeof(err_buf),
            "%s: getaddrinfo: %s",
            operation,
            gai_strerror(rc));
        *detail_out = blorp_string_from_buf(err_buf, (long)strlen(err_buf));
        return BLORP_UDP_ERROR_DNS;
    }
    return BLORP_UDP_ERROR_NONE;
}

static blorp_UdpErrorKind blorp_udp_socket_fd(
    blorp_UdpSocket* socket,
    int* fd_out,
    blorp_String** detail_out
) {
    if (fd_out) *fd_out = -1;
    if (detail_out) *detail_out = NULL;
    if (!socket) {
        if (detail_out) *detail_out = blorp_string_create("udp socket is closed");
        return BLORP_UDP_ERROR_CLOSED;
    }
    if (!fd_out) {
        if (detail_out) *detail_out = blorp_string_create("missing fd output");
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }
    pthread_mutex_lock(&socket->mutex);
    if (socket->state != BLORP_UDP_STATE_OPEN || socket->fd < 0) {
        pthread_mutex_unlock(&socket->mutex);
        if (detail_out) *detail_out = blorp_string_create("udp socket is closed");
        return BLORP_UDP_ERROR_CLOSED;
    }
    *fd_out = socket->fd;
    pthread_mutex_unlock(&socket->mutex);
    return BLORP_UDP_ERROR_NONE;
}

blorp_UdpSocketResult blorp_udp_socket_raw(void) {
    int fd = blorp_runtime_socket_cloexec(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        int errnum = errno;
        return blorp_udp_socket_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp socket", errnum));
    }
    if (blorp_io_reactor_set_nonblocking(fd) < 0) {
        int errnum = errno;
        close(fd);
        return blorp_udp_socket_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp socket nonblocking", errnum));
    }

    blorp_UdpSocket* socket =
        (blorp_UdpSocket*)blorp_malloc_checked(sizeof(blorp_UdpSocket));
    atomic_init(&socket->refcount, 1);
    socket->fd = fd;
    socket->generation =
        atomic_fetch_add_explicit(&blorp_udp_next_generation, 1, memory_order_relaxed);
    socket->state = BLORP_UDP_STATE_OPEN;
    socket->default_timeout_ms = -1;
    socket->read_waiter = NULL;
    socket->write_waiter = NULL;
    if (pthread_mutex_init(&socket->mutex, NULL) != 0) {
        close(socket->fd);
        free(socket);
        return blorp_udp_socket_error(
            BLORP_UDP_ERROR_OTHER,
            blorp_string_create("udp socket: failed to initialize mutex"));
    }
    return blorp_udp_socket_ok(socket);
}

static blorp_UdpVoidResult blorp_udp_bind_with_policy(
    blorp_UdpSocket* socket,
    blorp_String* host,
    long port,
    bool numeric_only
) {
    int fd = -1;
    blorp_String* detail = NULL;
    blorp_UdpErrorKind fd_kind = blorp_udp_socket_fd(socket, &fd, &detail);
    if (fd_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_void_error(fd_kind, detail);
    }

    struct addrinfo* res = NULL;
    blorp_UdpErrorKind resolve_kind =
        blorp_udp_resolve_addr(
            "udp bind", host, port, true, numeric_only, &res, &detail);
    if (resolve_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_void_error(resolve_kind, detail);
    }

    if (bind(fd, res->ai_addr, res->ai_addrlen) < 0) {
        int errnum = errno;
        freeaddrinfo(res);
        return blorp_udp_void_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp bind", errnum));
    }
    freeaddrinfo(res);
    return blorp_udp_void_ok();
}

blorp_UdpVoidResult blorp_udp_bind_raw(
    blorp_UdpSocket* socket,
    blorp_String* host,
    long port
) {
    return blorp_udp_bind_with_policy(socket, host, port, false);
}

blorp_UdpVoidResult blorp_udp_bind_numeric_raw(
    blorp_UdpSocket* socket,
    blorp_String* host,
    long port
) {
    return blorp_udp_bind_with_policy(socket, host, port, true);
}

static blorp_UdpIntResult blorp_udp_send_to_with_policy(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port,
    bool numeric_only
) {
    int fd = -1;
    blorp_String* detail = NULL;
    blorp_UdpErrorKind fd_kind = blorp_udp_socket_fd(socket, &fd, &detail);
    if (fd_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_int_error(fd_kind, detail);
    }
    if (!blorp_udp_payload_is_valid(data)) {
        return blorp_udp_int_error(
            BLORP_UDP_ERROR_INVALID_INPUT,
            blorp_string_create("payload bytes are invalid"));
    }

    struct addrinfo* res = NULL;
    blorp_UdpErrorKind resolve_kind =
        blorp_udp_resolve_addr(
            "udp send_to", host, port, false, numeric_only, &res, &detail);
    if (resolve_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_int_error(resolve_kind, detail);
    }

    while (true) {
        ssize_t n = sendto(
            fd,
            data->data,
            (size_t)data->len,
            0,
            res->ai_addr,
            res->ai_addrlen);
        if (n >= 0) {
            freeaddrinfo(res);
            return blorp_udp_int_ok((long)n);
        }
        int errnum = errno;
        if (errnum == EINTR) continue;
        freeaddrinfo(res);
        return blorp_udp_int_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp send_to", errnum));
    }
}

blorp_UdpIntResult blorp_udp_send_to_raw(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port
) {
    return blorp_udp_send_to_with_policy(socket, data, host, port, false);
}

blorp_UdpIntResult blorp_udp_send_to_numeric_raw(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port
) {
    return blorp_udp_send_to_with_policy(socket, data, host, port, true);
}

static blorp_UdpIntResult blorp_udp_send_to_wait_with_policy(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port,
    bool numeric_only
) {
    if (!socket) {
        return blorp_udp_int_error(
            BLORP_UDP_ERROR_CLOSED,
            blorp_string_create("udp socket is closed"));
    }
    if (!blorp_udp_payload_is_valid(data)) {
        return blorp_udp_int_error(
            BLORP_UDP_ERROR_INVALID_INPUT,
            blorp_string_create("payload bytes are invalid"));
    }

    blorp_String* detail = NULL;
    struct addrinfo* res = NULL;
    blorp_UdpErrorKind resolve_kind =
        blorp_udp_resolve_addr(
            "udp send_to_wait",
            host,
            port,
            false,
            numeric_only,
            &res,
            &detail);
    if (resolve_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_int_error(resolve_kind, detail);
    }
    if (!res || res->ai_addrlen > sizeof(struct sockaddr_storage)) {
        if (res) freeaddrinfo(res);
        return blorp_udp_int_error(
            BLORP_UDP_ERROR_INVALID_INPUT,
            blorp_string_create("udp send_to_wait: resolved address is invalid"));
    }

    struct sockaddr_storage addr;
    memset(&addr, 0, sizeof(addr));
    memcpy(&addr, res->ai_addr, res->ai_addrlen);
    socklen_t addr_len = res->ai_addrlen;
    freeaddrinfo(res);

    blorp_udp_socket_retain(socket);
    blorp_CancelCleanupFrame socket_cleanup;
    blorp_udp_socket_operation_cleanup_push(
        &socket_cleanup, &socket, socket);
    blorp_UdpIntResult result;

    while (true) {
        if (__blorp_cancel_current_task_if_requested()) {
            result = blorp_udp_int_error(
                BLORP_UDP_ERROR_INTERRUPTED,
                blorp_string_create("udp send_to_wait: cancelled"));
            goto finish;
        }

        long fd = -1;
        uint64_t generation = 0;
        long timeout_ms = -1;
        if (blorp_udp_socket_begin_op(
                socket, &fd, &generation, &timeout_ms) < 0) {
            result = blorp_udp_int_error(
                BLORP_UDP_ERROR_CLOSED,
                blorp_string_create("udp socket is closed"));
            goto finish;
        }

        ssize_t n = sendto(
            (int)fd,
            data->data,
            (size_t)data->len,
            0,
            (const struct sockaddr*)&addr,
            addr_len);
        int errnum = errno;
        blorp_udp_socket_end_op(socket);

        if (n >= 0) {
            result = blorp_udp_int_ok((long)n);
            goto finish;
        }
        if (errnum == EINTR) continue;
        if (errnum == EAGAIN || errnum == EWOULDBLOCK) {
            blorp_IoWakeReason reason;
            if (blorp_udp_socket_wait_for_reactor(
                    socket,
                    BLORP_IO_WAIT_WRITE,
                    BLORP_IO_INTEREST_WRITE,
                    (int)fd,
                    generation,
                    timeout_ms,
                    &reason) != 0) {
                result = blorp_udp_int_error(
                    BLORP_UDP_ERROR_OTHER,
                    blorp_string_create("udp send_to_wait: reactor unavailable"));
                goto finish;
            }

            switch (reason) {
                case BLORP_IO_WAKE_READY:
                    continue;
                case BLORP_IO_WAKE_TIMEOUT:
                    result = blorp_udp_int_error(
                        BLORP_UDP_ERROR_TIMED_OUT,
                        blorp_string_create("udp send_to_wait: timed out"));
                    goto finish;
                case BLORP_IO_WAKE_CANCELLED:
                    (void)__blorp_cancel_current_task_if_requested();
                    result = blorp_udp_int_error(
                        BLORP_UDP_ERROR_INTERRUPTED,
                        blorp_string_create("udp send_to_wait: cancelled"));
                    goto finish;
                case BLORP_IO_WAKE_BUSY:
                    result = blorp_udp_int_error(
                        BLORP_UDP_ERROR_BUSY,
                        blorp_string_create(
                            "udp send_to_wait: send already in progress"));
                    goto finish;
                case BLORP_IO_WAKE_CLOSED:
                case BLORP_IO_WAKE_NONE:
                default:
                    result = blorp_udp_int_error(
                        BLORP_UDP_ERROR_CLOSED,
                        blorp_string_create("udp socket is closed"));
                    goto finish;
            }
        }

        result = blorp_udp_int_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp send_to_wait", errnum));
        goto finish;
    }

finish:
    blorp_udp_socket_operation_cleanup_pop(&socket);
    blorp_udp_socket_release(socket);
    return result;
}

blorp_UdpIntResult blorp_udp_send_to_wait_raw(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port
) {
    return blorp_udp_send_to_wait_with_policy(socket, data, host, port, false);
}

blorp_UdpIntResult blorp_udp_send_to_wait_numeric_raw(
    blorp_UdpSocket* socket,
    blorp_Bytes* data,
    blorp_String* host,
    long port
) {
    return blorp_udp_send_to_wait_with_policy(socket, data, host, port, true);
}

static blorp_UdpErrorKind blorp_udp_sockaddr_to_host_port(
    const struct sockaddr_storage* addr,
    socklen_t addr_len,
    blorp_String** host_out,
    long* port_out,
    blorp_String** detail_out
) {
    if (host_out) *host_out = NULL;
    if (port_out) *port_out = 0;
    if (detail_out) *detail_out = NULL;
    if (!addr || !host_out || !port_out || !detail_out) {
        if (detail_out) {
            *detail_out = blorp_string_create("udp recv_from: missing address output");
        }
        return BLORP_UDP_ERROR_INVALID_INPUT;
    }

    char host[NI_MAXHOST];
    char service[NI_MAXSERV];
    int rc = getnameinfo(
        (const struct sockaddr*)addr,
        addr_len,
        host,
        sizeof(host),
        service,
        sizeof(service),
        NI_NUMERICHOST | NI_NUMERICSERV);
    if (rc != 0) {
        char err_buf[256];
        snprintf(
            err_buf,
            sizeof(err_buf),
            "udp recv_from: getnameinfo: %s",
            gai_strerror(rc));
        *detail_out = blorp_string_from_buf(err_buf, (long)strlen(err_buf));
        return BLORP_UDP_ERROR_DNS;
    }

    char* end = NULL;
    errno = 0;
    long parsed_port = strtol(service, &end, 10);
    if (errno != 0 || !end || *end != '\0' || parsed_port < 0 ||
        parsed_port > 65535) {
        *detail_out = blorp_string_create("udp recv_from: invalid source port");
        return BLORP_UDP_ERROR_OTHER;
    }

    *host_out = blorp_string_from_buf(host, (long)strlen(host));
    *port_out = parsed_port;
    return BLORP_UDP_ERROR_NONE;
}

blorp_UdpDatagramResult blorp_udp_recv_from_raw(
    blorp_UdpSocket* socket,
    long max_bytes
) {
    if (max_bytes <= 0 || max_bytes > 65535) {
        return blorp_udp_datagram_error(
            BLORP_UDP_ERROR_INVALID_INPUT,
            blorp_string_create("max_bytes must be between 1 and 65535"));
    }
    if (!socket) {
        return blorp_udp_datagram_error(
            BLORP_UDP_ERROR_CLOSED,
            blorp_string_create("udp socket is closed"));
    }

    blorp_udp_socket_retain(socket);
    blorp_CancelCleanupFrame socket_cleanup;
    blorp_udp_socket_operation_cleanup_push(
        &socket_cleanup, &socket, socket);
    blorp_UdpDatagramResult result;

    while (true) {
        if (__blorp_cancel_current_task_if_requested()) {
            result = blorp_udp_datagram_error(
                BLORP_UDP_ERROR_INTERRUPTED,
                blorp_string_create("udp recv_from: cancelled"));
            goto finish;
        }

        long fd = -1;
        uint64_t generation = 0;
        long timeout_ms = -1;
        if (blorp_udp_socket_begin_op(
                socket, &fd, &generation, &timeout_ms) < 0) {
            result = blorp_udp_datagram_error(
                BLORP_UDP_ERROR_CLOSED,
                blorp_string_create("udp socket is closed"));
            goto finish;
        }

        blorp_Bytes* buf = blorp_bytes_new(max_bytes);
        struct sockaddr_storage addr;
        socklen_t addr_len = sizeof(addr);
        ssize_t n = recvfrom(
            (int)fd,
            buf->data,
            (size_t)max_bytes,
            0,
            (struct sockaddr*)&addr,
            &addr_len);
        if (n >= 0) {
            blorp_udp_socket_end_op(socket);
            buf->len = (long)n;
            blorp_String* host = NULL;
            long port = 0;
            blorp_String* detail = NULL;
            blorp_UdpErrorKind addr_kind =
                blorp_udp_sockaddr_to_host_port(
                    &addr, addr_len, &host, &port, &detail);
            if (addr_kind != BLORP_UDP_ERROR_NONE) {
                blorp_release((void*)buf);
                result = blorp_udp_datagram_error(addr_kind, detail);
                goto finish;
            }
            result = blorp_udp_datagram_ok(buf, host, port);
            goto finish;
        }

        int errnum = errno;
        blorp_udp_socket_end_op(socket);
        blorp_release((void*)buf);

        if (errnum == EINTR) continue;
        if (errnum == EAGAIN || errnum == EWOULDBLOCK) {
            blorp_IoWakeReason reason;
            if (blorp_udp_socket_wait_for_reactor(
                    socket,
                    BLORP_IO_WAIT_READ,
                    BLORP_IO_INTEREST_READ,
                    (int)fd,
                    generation,
                    timeout_ms,
                    &reason) != 0) {
                result = blorp_udp_datagram_error(
                    BLORP_UDP_ERROR_OTHER,
                    blorp_string_create("udp recv_from: reactor unavailable"));
                goto finish;
            }

            switch (reason) {
                case BLORP_IO_WAKE_READY:
                    continue;
                case BLORP_IO_WAKE_TIMEOUT:
                    result = blorp_udp_datagram_error(
                        BLORP_UDP_ERROR_TIMED_OUT,
                        blorp_string_create("udp recv_from: timed out"));
                    goto finish;
                case BLORP_IO_WAKE_CANCELLED:
                    (void)__blorp_cancel_current_task_if_requested();
                    result = blorp_udp_datagram_error(
                        BLORP_UDP_ERROR_INTERRUPTED,
                        blorp_string_create("udp recv_from: cancelled"));
                    goto finish;
                case BLORP_IO_WAKE_BUSY:
                    result = blorp_udp_datagram_error(
                        BLORP_UDP_ERROR_BUSY,
                        blorp_string_create(
                            "udp recv_from: receive already in progress"));
                    goto finish;
                case BLORP_IO_WAKE_CLOSED:
                case BLORP_IO_WAKE_NONE:
                default:
                    result = blorp_udp_datagram_error(
                        BLORP_UDP_ERROR_CLOSED,
                        blorp_string_create("udp socket is closed"));
                    goto finish;
            }
        }
        result = blorp_udp_datagram_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp recv_from", errnum));
        goto finish;
    }

finish:
    blorp_udp_socket_operation_cleanup_pop(&socket);
    blorp_udp_socket_release(socket);
    return result;
}

blorp_UdpIntResult blorp_udp_local_port_raw(blorp_UdpSocket* socket) {
    int fd = -1;
    blorp_String* detail = NULL;
    blorp_UdpErrorKind fd_kind = blorp_udp_socket_fd(socket, &fd, &detail);
    if (fd_kind != BLORP_UDP_ERROR_NONE) {
        return blorp_udp_int_error(fd_kind, detail);
    }

    struct sockaddr_storage addr;
    socklen_t addr_len = sizeof(addr);
    if (getsockname(fd, (struct sockaddr*)&addr, &addr_len) < 0) {
        int errnum = errno;
        return blorp_udp_int_error(
            blorp_udp_error_kind_from_errno(errnum),
            blorp_udp_errno_detail("udp local_port", errnum));
    }

    switch (addr.ss_family) {
        case AF_INET:
            return blorp_udp_int_ok(
                (long)ntohs(((struct sockaddr_in*)&addr)->sin_port));
        case AF_INET6:
            return blorp_udp_int_ok(
                (long)ntohs(((struct sockaddr_in6*)&addr)->sin6_port));
        default:
            return blorp_udp_int_error(
                BLORP_UDP_ERROR_UNSUPPORTED,
                blorp_string_create("udp local_port: unsupported address family"));
    }
}

void blorp_udp_close_socket(blorp_UdpSocket* socket) {
    if (!socket) return;
    int closed_fd = -1;
    uint64_t closed_generation = 0;
    blorp_IoWaiterList waiters =
        blorp_udp_socket_close_and_extract_waiters(
            socket, BLORP_IO_WAKE_CLOSED, &closed_fd, &closed_generation);
    if (closed_fd >= 0 && blorp_io_reactor_is_started()) {
        (void)blorp_io_reactor_unregister_fd_generation(
            closed_fd, closed_generation);
    }
    blorp_io_waiter_wake_all(&waiters);
    blorp_udp_socket_release(socket);
}

// ============================================================================
// Dict (Hash Map) Operations
// ============================================================================

// Forward declaration for blorp_Tuple (defined later)
// release_mask: bit i set = elem[i] is refcounted and should be released on destruction
typedef struct { blorp_Object header; long arity; long release_mask; void* elem[]; } blorp_Tuple;
blorp_Tuple* blorp_tuple_new(long arity, ...);

// Tuple destructor: releases refcounted elements based on release_mask
void blorp_tuple_destructor(void* obj) {
    blorp_Tuple* t = (blorp_Tuple*)obj;
    for (long i = 0; i < t->arity; i++) {
        if ((t->release_mask >> i) & 1) {
            if (t->elem[i]) blorp_release(t->elem[i]);
        }
    }
}

// Set release mask on tuple and install destructor
static inline void blorp_tuple_set_rc(blorp_Tuple* t, long mask) {
    t->release_mask = mask;
    BLORP_SET_DESTRUCTOR(t, blorp_tuple_destructor);
}

// Dict: Swiss table — open addressing with group-of-16 probing
// Meta byte: 0xFF=empty, 0x80=deleted, 0x00-0x7F=occupied (h2 fingerprint)
// Occupied slots have high bit 0; empty/deleted have high bit 1.
// SIMD can compare 16 meta bytes at once to find h2 matches or empty slots.
#define DICT_META_EMPTY   0xFF
#define DICT_META_DELETED 0x80
#define DICT_GROUP_SIZE   16

typedef struct {
    blorp_Object header;
    long size;           // Number of live entries
    long order_len;      // Length of order[] including holes (-1 entries from removal)
    long capacity;       // Power of 2 (hash table capacity)
    long mask;           // capacity - 1 (for & instead of %)
    long grow_at;        // Rehash threshold (capacity * 7 / 10)
    void** keys;         // Flat array [capacity]
    void** values;       // Flat array [capacity]
    uint8_t* meta;       // [capacity]: metadata bytes
    long* order;         // Dense array of slot indices [size], preserves insertion order
    long* order_index;   // Reverse map: slot -> position in order[] (-1 if unoccupied)
    unsigned long (*hash_fn)(void*);
    bool (*eq_fn)(void*, void*);
    void (*key_release)(void*);    // ARC release for refcounted keys (NULL for primitives)
    void (*value_release)(void*);  // ARC release for refcounted values (NULL for primitives)
} blorp_Dict;

// Type-specific hash functions
// Random seed for hash functions — prevents hash collision DoS
static uint64_t __blorp_hash_seed = 0;

__attribute__((constructor))
static void __blorp_init_hash_seed(void) {
    blorp_fill_random_or_die(&__blorp_hash_seed, sizeof(__blorp_hash_seed));
}

static inline unsigned long blorp_dict_hash_int(void* key) {
    unsigned long val = (unsigned long)(intptr_t)key;
    val ^= __blorp_hash_seed;
    val = (val ^ (val >> 30)) * 0xbf58476d1ce4e5b9UL;
    val = (val ^ (val >> 27)) * 0x94d049bb133111ebUL;
    return val ^ (val >> 31);
}

// wyhash core: fast non-cryptographic hash (processes 8 bytes/iteration)
static inline uint64_t __wyhash_read8(const uint8_t* p) {
    uint64_t v; memcpy(&v, p, 8); return v;
}
static inline uint64_t __wyhash_read4(const uint8_t* p) {
    uint32_t v; memcpy(&v, p, 4); return v;
}
static inline uint64_t __wyhash_mum(uint64_t a, uint64_t b) {
    __uint128_t r = (__uint128_t)a * b;
    return (uint64_t)(r >> 64) ^ (uint64_t)r;
}
static inline uint64_t __wyhash_mix(uint64_t a, uint64_t b) {
    return __wyhash_mum(a ^ 0x53c5ca59e6b02c97ULL, b ^ 0x6c62272e07bb0142ULL);
}

static unsigned long blorp_dict_hash_string(void* key) {
    blorp_String* str = (blorp_String*)key;
    if (!str || str->len == 0) return __blorp_hash_seed;
    const uint8_t* p = (const uint8_t*)str->data;
    long len = str->len;
    uint64_t seed = __blorp_hash_seed;
    uint64_t a, b;
    if (len <= 16) {
        if (len >= 4) {
            a = (__wyhash_read4(p) << 32) | __wyhash_read4(p + ((len >> 3) << 2));
            b = (__wyhash_read4(p + len - 4) << 32) | __wyhash_read4(p + len - 4 - ((len >> 3) << 2));
        } else if (len > 0) {
            a = ((uint64_t)p[0] << 16) | ((uint64_t)p[len >> 1] << 8) | p[len - 1];
            b = 0;
        } else {
            a = b = 0;
        }
    } else {
        long i = len;
        if (i > 48) {
            uint64_t s1 = seed, s2 = seed;
            do {
                seed = __wyhash_mix(__wyhash_read8(p) ^ 0x2d358dccaa6c78a5ULL, __wyhash_read8(p + 8) ^ seed);
                s1 = __wyhash_mix(__wyhash_read8(p + 16) ^ 0xa0761d6478bd642fULL, __wyhash_read8(p + 24) ^ s1);
                s2 = __wyhash_mix(__wyhash_read8(p + 32) ^ 0xe7037ed1a0b428dbULL, __wyhash_read8(p + 40) ^ s2);
                p += 48; i -= 48;
            } while (i > 48);
            seed ^= s1 ^ s2;
        }
        while (i > 16) {
            seed = __wyhash_mix(__wyhash_read8(p) ^ 0x2d358dccaa6c78a5ULL, __wyhash_read8(p + 8) ^ seed);
            i -= 16; p += 16;
        }
        a = __wyhash_read8(p + i - 16);
        b = __wyhash_read8(p + i - 8);
    }
    return (unsigned long)__wyhash_mix(0x2d358dccaa6c78a5ULL ^ (uint64_t)len, __wyhash_mum(a ^ 0x2d358dccaa6c78a5ULL, b ^ seed));
}

static bool blorp_dict_key_eq_int(void* a, void* b) {
    return a == b;
}

static bool blorp_dict_key_eq_string(void* a, void* b) {
    return blorp_string_eq((blorp_String*)a, (blorp_String*)b);
}

static unsigned long blorp_dict_hash_float(void* key) {
    union { void* p; double d; } u;
    u.p = key;
    double d = u.d;
    if (d == 0.0) d = 0.0;
    union { double dd; unsigned long ul; } bits;
    bits.dd = d;
    unsigned long val = bits.ul ^ __blorp_hash_seed;
    val = (val ^ (val >> 30)) * 0xbf58476d1ce4e5b9UL;
    val = (val ^ (val >> 27)) * 0x94d049bb133111ebUL;
    return val ^ (val >> 31);
}

static bool blorp_dict_key_eq_float(void* a, void* b) {
    union { void* p; double d; } ua, ub;
    ua.p = a;
    ub.p = b;
    return ua.d == ub.d;
}

// ---------------------------------------------------------------------------
// Hashable trait wrappers
// ---------------------------------------------------------------------------
// Typed wrappers around the dict-internal hashers, callable from generated
// blorp code via the `hash()` trait method. The wrappers match blorp's
// C calling convention (typed args, `long` return) so Core specialization
// can emit a direct function call without casting. The underlying hash is
// seeded wyhash / SplitMix on primitive bit-patterns — HashDoS-resistant
// but NOT cryptographic. For SHA-256 and friends see standard_library/src/hash.brp.
long blorp_hash_int(long k) {
    return (long)blorp_dict_hash_int((void*)(intptr_t)k);
}

long blorp_hash_string(blorp_String* s) {
    return (long)blorp_dict_hash_string((void*)s);
}

long blorp_hash_float(double d) {
    union { double dd; void* p; } u;
    u.dd = d;
    return (long)blorp_dict_hash_float(u.p);
}

// Binary hash mixer for multi-field Hashable impls. The mixing
// constants come from the boost::hash_combine pattern (the golden-
// ratio magic number) extended with SplitMix finalizers matching
// [blorp_dict_hash_int] for consistency. Non-commutative: the
// user's field-order choice is preserved in the chain, so two
// records that differ only in field values at different positions
// hash differently.
long blorp_hash_combine(long seed, long value) {
    unsigned long s = (unsigned long)seed;
    unsigned long v = (unsigned long)value;
    unsigned long h = s ^ (v + 0x9e3779b97f4a7c15UL + (s << 12) + (s >> 4));
    h = (h ^ (h >> 30)) * 0xbf58476d1ce4e5b9UL;
    h = (h ^ (h >> 27)) * 0x94d049bb133111ebUL;
    return (long)(h ^ (h >> 31));
}

// Compute h2 fingerprint: low 7 bits from top of hash (0x00-0x7F, high bit always 0)
static inline uint8_t blorp_dict_h2(unsigned long hash) {
    return (uint8_t)(hash >> 57) & 0x7F;
}

// Find slot for key via linear probing with Swiss-table-style h2 fingerprints.
// Meta encoding: 0xFF=empty, 0x80=deleted, 0x00-0x7F=h2 (occupied).
// Returns slot index if found, -1 if not found.
// If out_insert_slot is non-NULL and key not found, writes the first available slot.
static long blorp_dict_find_slot(blorp_Dict* dict, void* key, unsigned long hash, long* out_insert_slot) {
    uint8_t h2 = blorp_dict_h2(hash);
    long i = (long)(hash & (unsigned long)dict->mask);
    long first_available = -1;
    long probes = 0;
    while (probes <= dict->capacity) {
        uint8_t m = dict->meta[i];
        if (m == h2 && dict->eq_fn(dict->keys[i], key)) {
            return i;  // Found
        }
        if (m == DICT_META_EMPTY) {
            // Empty slot: key is definitely absent
            if (out_insert_slot) {
                *out_insert_slot = (first_available >= 0) ? first_available : i;
            }
            return -1;
        }
        if (m == DICT_META_DELETED && first_available == -1) {
            first_available = i;
        }
        i = (i + 1) & dict->mask;
        probes++;
    }
    if (out_insert_slot && first_available >= 0) {
        *out_insert_slot = first_available;
    }
    return -1;
}

// Allocate dict arrays for a given capacity
static void blorp_dict_alloc_arrays(blorp_Dict* dict, long capacity) {
    dict->capacity = capacity;
    dict->mask = capacity - 1;
    dict->grow_at = capacity * 7 / 10;
    dict->keys = (void**)blorp_calloc_checked(capacity, sizeof(void*));
    dict->values = (void**)blorp_calloc_checked(capacity, sizeof(void*));
    dict->meta = (uint8_t*)blorp_simd_alloc(capacity);
    memset(dict->meta, DICT_META_EMPTY, capacity);
    dict->order = (long*)blorp_malloc_checked(blorp_checked_mul(capacity, sizeof(long)));
    dict->order_index = (long*)blorp_malloc_checked(blorp_checked_mul(capacity, sizeof(long)));
    memset(dict->order_index, 0xFF, capacity * sizeof(long));
}

static long blorp_hash_capacity_at_least(long min_cap) {
    if (min_cap <= 16) return 16;
    const unsigned long max_cap = ((unsigned long)LONG_MAX >> 1) + 1UL;
    unsigned long target = (unsigned long)min_cap;
    unsigned long cap = 16;
    while (cap < target) {
        if (cap >= max_cap) return (long)max_cap;
        cap <<= 1;
    }
    return (long)cap;
}

static long blorp_dict_capacity_for_len(long len) {
    if (len <= 0) return 16;
    const unsigned long max_long = (unsigned long)LONG_MAX;
    unsigned long target_len = (unsigned long)len;
    if (target_len > max_long / 10UL) {
        return blorp_hash_capacity_at_least(LONG_MAX);
    }
    unsigned long min_cap = (target_len * 10UL + 6UL) / 7UL;
    if (min_cap > max_long) return blorp_hash_capacity_at_least(LONG_MAX);
    return blorp_hash_capacity_at_least((long)min_cap);
}

static void blorp_dict_destroy(void* obj) {
    blorp_Dict* dict = (blorp_Dict*)obj;
    for (long i = 0; i < dict->order_len; i++) {
        long slot = dict->order[i];
        if (slot < 0) continue;
        if (dict->key_release && dict->keys[slot]) dict->key_release(dict->keys[slot]);
        if (dict->value_release && dict->values[slot]) dict->value_release(dict->values[slot]);
    }
    free(dict->keys);
    free(dict->values);
    free(dict->meta);
    free(dict->order);
    free(dict->order_index);
}

blorp_Dict* blorp_dict_new(void) {
    long initial_capacity = 16;
    blorp_Dict* dict = (blorp_Dict*)blorp_alloc(sizeof(blorp_Dict));
    dict->size = 0;
    dict->order_len = 0;
    blorp_dict_alloc_arrays(dict, initial_capacity);
    dict->hash_fn = blorp_dict_hash_int;
    dict->eq_fn = blorp_dict_key_eq_int;
    dict->key_release = NULL;
    dict->value_release = NULL;
    BLORP_SET_DESTRUCTOR(dict, blorp_dict_destroy);
    return dict;
}

blorp_Dict* blorp_dict_new_string(void) {
    blorp_Dict* dict = blorp_dict_new();
    dict->hash_fn = blorp_dict_hash_string;
    dict->eq_fn = blorp_dict_key_eq_string;
    dict->key_release = blorp_elem_release_fn;
    return dict;
}

blorp_Dict* blorp_dict_new_float(void) {
    blorp_Dict* dict = blorp_dict_new();
    dict->hash_fn = blorp_dict_hash_float;
    dict->eq_fn = blorp_dict_key_eq_float;
    return dict;
}

void blorp_dict_init_key_string(blorp_Dict* dict) {
    if (!dict || dict->hash_fn == blorp_dict_hash_string) return;
    dict->hash_fn = blorp_dict_hash_string;
    dict->eq_fn = blorp_dict_key_eq_string;
    dict->key_release = blorp_elem_release_fn;
}

// ---------------------------------------------------------------------------
// Custom (user-defined Hashable+Equatable) key dispatch
// ---------------------------------------------------------------------------
// Takes caller-supplied hash_fn and eq_fn for keys whose types live outside
// the primitive set. The codegen for [Dict[UserType, V]] (where UserType
// has source-level Hashable + Equatable impls) routes construction through
// this entry point, passing the user impl functions with ABI-compatible
// pointer casts. key_release is NULL for value-type keys (structs held by
// value boxed into void*) and the standard ARC release otherwise.
//
// The cast of the user's [Hashable_hash_T(T*) -> long] to
// [unsigned long (*)(void*)] is technically UB under strict C, but every
// platform blorp targets (x86_64 / aarch64 macOS, Linux, BSD) has
// ABI-compatible layouts for pointer-arg + word-return. If CFI is ever
// enabled, this call site needs per-type shims instead.
blorp_Dict* blorp_dict_new_custom(
    unsigned long (*hash_fn)(void*),
    bool (*eq_fn)(void*, void*),
    void (*key_release)(void*)
) {
    blorp_Dict* dict = blorp_dict_new();
    dict->hash_fn = hash_fn;
    dict->eq_fn = eq_fn;
    dict->key_release = key_release;
    return dict;
}

void blorp_dict_init_key_float(blorp_Dict* dict) {
    if (!dict || dict->hash_fn == blorp_dict_hash_float) return;
    dict->hash_fn = blorp_dict_hash_float;
    dict->eq_fn = blorp_dict_key_eq_float;
}

void blorp_dict_set_value_release(blorp_Dict* dict, void (*release_fn)(void*)) {
    if (!dict || dict->value_release == release_fn) return;
    if (!dict->value_release && release_fn) {
        for (long i = 0; i < dict->order_len; i++) {
            long slot = dict->order[i];
            if (slot < 0) continue;
            if (dict->values[slot]) blorp_retain(dict->values[slot]);
        }
    }
    dict->value_release = release_fn;
}

blorp_Option* blorp_dict_get(blorp_Dict* dict, void* key) {
    if (__builtin_expect(!dict, 0)) return blorp_option_none();
    unsigned long hash = dict->hash_fn(key);
    long slot = blorp_dict_find_slot(dict, key, hash, NULL);
    if (slot >= 0) {
        void* val = dict->values[slot];
        if (dict->value_release && val) blorp_retain(val);
        blorp_Option* opt = blorp_option_some(val);
        if (dict->value_release) opt->release_mask = 1UL;
        return opt;
    }
    return blorp_option_none();
}

bool blorp_dict_get_raw(blorp_Dict* dict, void* key, void** out_value) {
    if (__builtin_expect(!dict, 0)) return false;
    unsigned long hash = dict->hash_fn(key);
    long slot = blorp_dict_find_slot(dict, key, hash, NULL);
    if (slot >= 0) {
        if (out_value) *out_value = dict->values[slot];
        return true;
    }
    return false;
}

void* blorp_dict_get_nullable(blorp_Dict* dict, void* key) {
    if (__builtin_expect(!dict, 0)) return NULL;
    unsigned long hash = dict->hash_fn(key);
    long slot = blorp_dict_find_slot(dict, key, hash, NULL);
    if (slot >= 0) {
        void* val = dict->values[slot];
        if (dict->value_release && val) blorp_retain(val);
        return val;
    }
    return NULL;
}

blorp_StackOption_Int blorp_dict_get_int(blorp_Dict* dict, void* key) {
    if (__builtin_expect(!dict, 0)) return blorp_stack_option_int_none();
    unsigned long hash = dict->hash_fn(key);
    long slot = blorp_dict_find_slot(dict, key, hash, NULL);
    if (slot >= 0) {
        return blorp_stack_option_int_some((long)dict->values[slot]);
    }
    return blorp_stack_option_int_none();
}

