static bool stream_filter_map_pull_nullable(blorp_Stream* self, void** out) {
    StreamFilterMapState* st = (StreamFilterMapState*)self->state;
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!st->inner->pull(st->inner, &val)) return false;
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                st->inner->elem_layout, &val_cleanup, &val);
        void* opt = blorp_call1(st->func, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_stream_release_pulled_if_owned(st->inner, val);
        if (opt) {
            *out = opt;
            return true;
        }
    }
}
blorp_Stream* blorp_stream_filter_map_nullable(blorp_Stream* inner, blorp_Closure* func) {
    blorp_Stream* s = blorp_stream_new();
    s->elem_layout = BLORP_STREAM_ELEM_OWNED_ARC;
    StreamFilterMapState* st = malloc(sizeof(StreamFilterMapState));
    st->inner = inner;
    if (inner) blorp_retain((blorp_Object*)inner);
    st->func = func;
    if (func) blorp_retain((blorp_Object*)func);
    s->state = st;
    s->pull = stream_filter_map_pull_nullable;
    s->state_cleanup = stream_map_cleanup;
    return s;
}

// --- take ---
static bool stream_take_pull(blorp_Stream* self, void** out) {
    StreamTakeState* st = (StreamTakeState*)self->state;
    if (st->remaining <= 0) return false;
    st->remaining--;
    return st->inner->pull(st->inner, out);
}
static void stream_take_cleanup(blorp_Stream* self) {
    StreamTakeState* st = (StreamTakeState*)self->state;
    if (st->inner) blorp_release((blorp_Object*)st->inner);
    free(st);
}
blorp_Stream* blorp_stream_take(blorp_Stream* inner, long n) {
    blorp_Stream* s = blorp_stream_new();
    s->elem_layout = inner->elem_layout;
    StreamTakeState* st = malloc(sizeof(StreamTakeState));
    st->inner = inner;
    if (inner) blorp_retain((blorp_Object*)inner);
    st->remaining = n;
    s->state = st;
    s->pull = stream_take_pull;
    s->state_cleanup = stream_take_cleanup;
    return s;
}

// --- drop ---
static bool stream_drop_pull(blorp_Stream* self, void** out) {
    StreamDropState* st = (StreamDropState*)self->state;
    long cancel_check = 0;
    while (st->skipped < st->n) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        void* discard;
        if (!st->inner->pull(st->inner, &discard)) return false;
        blorp_stream_release_pulled_if_owned(st->inner, discard);
        st->skipped++;
    }
    return st->inner->pull(st->inner, out);
}
static void stream_drop_cleanup(blorp_Stream* self) {
    StreamDropState* st = (StreamDropState*)self->state;
    if (st->inner) blorp_release((blorp_Object*)st->inner);
    free(st);
}
blorp_Stream* blorp_stream_drop(blorp_Stream* inner, long n) {
    blorp_Stream* s = blorp_stream_new();
    s->elem_layout = inner->elem_layout;
    StreamDropState* st = malloc(sizeof(StreamDropState));
    st->inner = inner;
    if (inner) blorp_retain((blorp_Object*)inner);
    st->skipped = 0;
    st->n = n;
    s->state = st;
    s->pull = stream_drop_pull;
    s->state_cleanup = stream_drop_cleanup;
    return s;
}

// --- take_while ---
static bool stream_take_while_pull(blorp_Stream* self, void** out) {
    StreamTakeWhileState* st = (StreamTakeWhileState*)self->state;
    if (st->done) return false;
    void* val;
    if (!st->inner->pull(st->inner, &val)) { st->done = true; return false; }
    blorp_CancelCleanupFrame val_cleanup;
    bool val_cleanup_active =
        blorp_stream_push_owned_pull_cleanup(
            st->inner->elem_layout, &val_cleanup, &val);
    if ((long)blorp_call1(st->pred, val)) {
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        *out = val;
        return true;
    }
    blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
    blorp_stream_release_pulled_if_owned(st->inner, val);
    st->done = true;
    return false;
}
static void stream_take_while_cleanup(blorp_Stream* self) {
    StreamTakeWhileState* st = (StreamTakeWhileState*)self->state;
    if (st->inner) blorp_release((blorp_Object*)st->inner);
    if (st->pred) blorp_release((blorp_Object*)st->pred);
    free(st);
}
blorp_Stream* blorp_stream_take_while(blorp_Stream* inner, blorp_Closure* pred) {
    blorp_Stream* s = blorp_stream_new();
    s->elem_layout = inner->elem_layout;
    StreamTakeWhileState* st = malloc(sizeof(StreamTakeWhileState));
    st->inner = inner;
    if (inner) blorp_retain((blorp_Object*)inner);
    st->pred = pred;
    if (pred) blorp_retain((blorp_Object*)pred);
    st->done = false;
    s->state = st;
    s->pull = stream_take_while_pull;
    s->state_cleanup = stream_take_while_cleanup;
    return s;
}

// --- enumerate ---
static bool stream_enum_pull(blorp_Stream* self, void** out) {
    StreamEnumState* st = (StreamEnumState*)self->state;
    void* val;
    if (!st->inner->pull(st->inner, &val)) return false;
    blorp_Tuple* t = blorp_tuple_new(2, (void*)(long)st->idx, val);
    if (blorp_stream_has_arc_elements(st->inner) && val) {
        if (blorp_stream_layout_is_borrowed_arc(st->inner->elem_layout)) {
            blorp_retain(val);
        }
        blorp_tuple_set_rc(t, 2UL);
    }
    st->idx++;
    *out = t;
    return true;
}
static void stream_enum_cleanup(blorp_Stream* self) {
    StreamEnumState* st = (StreamEnumState*)self->state;
    if (st->inner) blorp_release((blorp_Object*)st->inner);
    free(st);
}
blorp_Stream* blorp_stream_enumerate(blorp_Stream* inner) {
    blorp_Stream* s = blorp_stream_new();
    s->elem_layout = BLORP_STREAM_ELEM_OWNED_ARC;
    StreamEnumState* st = malloc(sizeof(StreamEnumState));
    st->inner = inner;
    if (inner) blorp_retain((blorp_Object*)inner);
    st->idx = 0;
    s->state = st;
    s->pull = stream_enum_pull;
    s->state_cleanup = stream_enum_cleanup;
    return s;
}

// --- Terminal: collect ---
blorp_List* blorp_stream_collect(blorp_Stream* stream) {
    if (!stream) return blorp_list_new(0);
    blorp_List* result = blorp_list_new(16);
    blorp_CancelCleanupFrame result_cleanup;
    blorp_task_cleanup_push(&result_cleanup, &result, result, blorp_cleanup_release_arc_value);
    if (blorp_stream_has_arc_elements(stream)) {
        extern void blorp_elem_release_fn(void*);
        result->elem_release = blorp_elem_release_fn;
    }
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!stream->pull(stream, &val)) break;
        if (blorp_stream_pulls_owned_arc(stream)) {
            result = blorp_list_append_owned(result, val);
        } else {
            result = blorp_list_append(result, val);
        }
        result_cleanup.value = result;
    }
    blorp_task_cleanup_pop_slot(&result);
    return result;
}

blorp_FallibleStreamListResult blorp_fallible_stream_collect_raw(
    blorp_FallibleStream* stream,
    uint8_t storage_mode,
    int16_t elem_size
) {
    if (!stream) {
        return blorp_fallible_stream_list_ok(
            blorp_list_new_layout(0, storage_mode, elem_size));
    }
    blorp_List* result = blorp_list_new_layout(16, storage_mode, elem_size);
    blorp_CancelCleanupFrame result_cleanup;
    blorp_task_cleanup_push(&result_cleanup, &result, result,
        blorp_cleanup_release_arc_value);
    if (result->storage_mode == BLORP_LIST_STORAGE_POINTER
        && blorp_stream_layout_is_arc(stream->elem_layout)) {
        result->elem_release = blorp_elem_release_fn;
    }
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            blorp_task_cleanup_pop_slot(&result);
            blorp_release(result);
            return blorp_fallible_stream_list_error(error);
        }
        if (blorp_fallible_stream_pulls_owned_arc(stream)) {
            result = blorp_list_append_owned(result, val);
        } else {
            result = blorp_list_append(result, val);
        }
        result_cleanup.value = result;
    }
    blorp_task_cleanup_pop_slot(&result);
    return blorp_fallible_stream_list_ok(result);
}

blorp_FallibleStreamValueResult blorp_fallible_stream_fold_raw(
    blorp_FallibleStream* stream,
    void* init,
    blorp_Closure* func,
    bool acc_is_rc
) {
    if (!stream || !func) return blorp_fallible_stream_value_ok(init);
    void* acc = init;
    void* val = NULL;
    long cancel_check = 0;
    blorp_CancelCleanupFrame acc_cleanup;
    if (acc_is_rc) {
        blorp_task_cleanup_push(
            &acc_cleanup, &acc, acc, blorp_cleanup_release_arc_value);
    }
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            if (acc_is_rc) {
                blorp_task_cleanup_pop_slot(&acc);
                if (acc) blorp_release(acc);
            }
            return blorp_fallible_stream_value_error(error);
        }
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        void* new_acc =
            ((void* (*)(void*, void*, void*))(func->func))(func->env, acc, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_fallible_stream_release_pulled_if_owned(stream, val);
        if (acc_is_rc && new_acc != acc && acc) blorp_release(acc);
        acc = new_acc;
        if (acc_is_rc) acc_cleanup.value = acc;
    }
    if (acc_is_rc) blorp_task_cleanup_pop_slot(&acc);
    return blorp_fallible_stream_value_ok(acc);
}

blorp_FallibleStreamIntResult blorp_fallible_stream_count_raw(
    blorp_FallibleStream* stream
) {
    if (!stream) return blorp_fallible_stream_int_ok(0);
    long n = 0;
    void* val = NULL;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            return blorp_fallible_stream_int_error(error);
        }
        n++;
        blorp_fallible_stream_release_pulled_if_owned(stream, val);
    }
    return blorp_fallible_stream_int_ok(n);
}

static blorp_FallibleStreamFindResult blorp_fallible_stream_find_raw_find(
    blorp_FallibleStream* stream,
    blorp_Closure* pred,
    bool retain_borrowed_match
) {
    if (!stream || !pred) return blorp_fallible_stream_find_ok(0, NULL);
    void* val = NULL;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            return blorp_fallible_stream_find_error(error);
        }
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        long keep = (long)blorp_call1(pred, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        if (keep) {
            if (retain_borrowed_match
                && blorp_stream_layout_is_borrowed_arc(stream->elem_layout)
                && val) {
                blorp_retain(val);
            }
            return blorp_fallible_stream_find_ok(1, val);
        }
        blorp_fallible_stream_release_pulled_if_owned(stream, val);
    }
    return blorp_fallible_stream_find_ok(0, NULL);
}

blorp_FallibleStreamValueResult blorp_fallible_stream_find_raw(
    blorp_FallibleStream* stream,
    blorp_Closure* pred
) {
    blorp_FallibleStreamFindResult found =
        blorp_fallible_stream_find_raw_find(stream, pred, true);
    if (found.error.domain != BLORP_FALLIBLE_STREAM_ERROR_DOMAIN_NONE) {
        return blorp_fallible_stream_value_error(found.error);
    }
    if (!found.found) {
        return blorp_fallible_stream_value_ok(blorp_option_none());
    }
    blorp_Option* opt = blorp_option_some(found.value);
    if (blorp_fallible_stream_has_arc_elements(stream)) {
        opt->release_mask = 1UL;
    }
    return blorp_fallible_stream_value_ok(opt);
}

blorp_FallibleStreamValueResult blorp_fallible_stream_find_raw_nullable(
    blorp_FallibleStream* stream,
    blorp_Closure* pred
) {
    blorp_FallibleStreamFindResult found =
        blorp_fallible_stream_find_raw_find(stream, pred, true);
    if (found.error.domain != BLORP_FALLIBLE_STREAM_ERROR_DOMAIN_NONE) {
        return blorp_fallible_stream_value_error(found.error);
    }
    return blorp_fallible_stream_value_ok(found.found ? found.value : NULL);
}

#define BLORP_DEFINE_FALLIBLE_STREAM_FIND_STACK_OPTION( \
    PUBLIC_SUFFIX, STACK_SUFFIX, NAME, CTYPE, UNBOX) \
blorp_FallibleStreamValueResult blorp_fallible_stream_find_raw_##PUBLIC_SUFFIX( \
    blorp_FallibleStream* stream, \
    blorp_Closure* pred \
) { \
    blorp_FallibleStreamFindResult found = \
        blorp_fallible_stream_find_raw_find(stream, pred, false); \
    if (found.error.domain != BLORP_FALLIBLE_STREAM_ERROR_DOMAIN_NONE) { \
        return blorp_fallible_stream_value_error(found.error); \
    } \
    blorp_StackOption_##NAME opt = found.found \
        ? blorp_stack_option_##STACK_SUFFIX##_some((CTYPE)UNBOX(found.value)) \
        : blorp_stack_option_##STACK_SUFFIX##_none(); \
    if (found.found && blorp_fallible_stream_pulls_owned_arc(stream) \
        && found.value) { \
        blorp_release(found.value); \
    } \
    return blorp_fallible_stream_value_ok(blorp_box_struct(&opt, sizeof(opt))); \
}

