blorp_FallibleStreamBoolResult blorp_fallible_stream_any_raw(
    blorp_FallibleStream* stream,
    blorp_Closure* pred
) {
    if (!stream || !pred) return blorp_fallible_stream_bool_ok(0);
    void* val = NULL;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            return blorp_fallible_stream_bool_error(error);
        }
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        long keep = (long)blorp_call1(pred, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_fallible_stream_release_pulled_if_owned(stream, val);
        if (keep) return blorp_fallible_stream_bool_ok(1);
    }
    return blorp_fallible_stream_bool_ok(0);
}

blorp_FallibleStreamBoolResult blorp_fallible_stream_all_raw(
    blorp_FallibleStream* stream,
    blorp_Closure* pred
) {
    if (!stream || !pred) return blorp_fallible_stream_bool_ok(1);
    void* val = NULL;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        blorp_FallibleStreamError error = blorp_fallible_stream_no_error();
        blorp_FallibleStreamPullStatus status =
            stream->pull(stream, &val, &error);
        if (status == BLORP_FALLIBLE_STREAM_END) break;
        if (status == BLORP_FALLIBLE_STREAM_ERROR) {
            return blorp_fallible_stream_bool_error(error);
        }
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        long keep = (long)blorp_call1(pred, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_fallible_stream_release_pulled_if_owned(stream, val);
        if (!keep) return blorp_fallible_stream_bool_ok(0);
    }
    return blorp_fallible_stream_bool_ok(1);
}

// --- Terminal: fold ---
void* blorp_stream_fold(blorp_Stream* stream, void* init, blorp_Closure* func, bool acc_is_rc) {
    if (!stream || !func) return init;
    void* acc = init;
    void* val;
    long cancel_check = 0;
    blorp_CancelCleanupFrame acc_cleanup;
    if (acc_is_rc) {
        blorp_task_cleanup_push(&acc_cleanup, &acc, acc, blorp_cleanup_release_arc_value);
    }
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!stream->pull(stream, &val)) break;
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        void* new_acc = ((void* (*)(void*, void*, void*))(func->func))(func->env, acc, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_stream_release_pulled_if_owned(stream, val);
        if (acc_is_rc && new_acc != acc && acc) blorp_release(acc);
        acc = new_acc;
        if (acc_is_rc) acc_cleanup.value = acc;
    }
    if (acc_is_rc) blorp_task_cleanup_pop_slot(&acc);
    return acc;
}

// --- Terminal: count ---
long blorp_stream_count(blorp_Stream* stream) {
    if (!stream) return 0;
    long n = 0;
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!stream->pull(stream, &val)) break;
        n++;
        blorp_stream_release_pulled_if_owned(stream, val);
    }
    return n;
}

// --- Terminal: for_each ---
void blorp_stream_for_each(blorp_Stream* stream, blorp_Closure* func) {
    if (!stream || !func) return;
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!stream->pull(stream, &val)) break;
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        blorp_call1(func, val);
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_stream_release_pulled_if_owned(stream, val);
    }
}

// --- Terminal: find ---
bool blorp_stream_find_raw(blorp_Stream* stream, blorp_Closure* pred, void** out) {
    if (!stream || !pred) return false;
    void* val;
    long cancel_check = 0;
    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        if (!stream->pull(stream, &val)) break;
        blorp_CancelCleanupFrame val_cleanup;
        bool val_cleanup_active =
            blorp_stream_push_owned_pull_cleanup(
                stream->elem_layout, &val_cleanup, &val);
        if ((long)blorp_call1(pred, val)) {
            blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
            *out = val;
            return true;
        }
        blorp_stream_pop_owned_pull_cleanup(val_cleanup_active, &val);
        blorp_stream_release_pulled_if_owned(stream, val);
    }
    return false;
}

blorp_Option* blorp_stream_find(blorp_Stream* stream, blorp_Closure* pred) {
    void* val = NULL;
    if (!blorp_stream_find_raw(stream, pred, &val)) return blorp_option_none();
    if (stream && blorp_stream_layout_is_borrowed_arc(stream->elem_layout) && val) {
        blorp_retain(val);
    }
    blorp_Option* opt = blorp_option_some(val);
    if (blorp_stream_has_arc_elements(stream)) opt->release_mask = 1UL;
    return opt;
}

#define BLORP_DEFINE_STREAM_FIND_STACK_OPTION(PUBLIC_SUFFIX, STACK_SUFFIX, NAME, CTYPE, UNBOX) \
blorp_StackOption_##NAME blorp_stream_find_##PUBLIC_SUFFIX(blorp_Stream* stream, blorp_Closure* pred) { \
    void* value = NULL; \
    if (!blorp_stream_find_raw(stream, pred, &value)) return blorp_stack_option_##STACK_SUFFIX##_none(); \
    return blorp_stack_option_##STACK_SUFFIX##_some((CTYPE)UNBOX(value)); \
}

