blorp_List* blorp_read_all_lines(const blorp_String* path) {
    blorp_List* result = blorp_list_new(16);
    if (!path) return result;

    char* cpath = blorp_cstring_copy_if_valid(path);
    if (!cpath) return result;

    FILE* f = blorp_runtime_fopen_cloexec(cpath, "rb");
    free(cpath);

    if (!f) return result;

    char* line = NULL;
    size_t cap = 0;
    ssize_t len;
    while ((len = getline(&line, &cap, f)) != -1) {
        // Strip trailing \n, \r\n, or \r
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            len--;
        }
        blorp_String* s = blorp_string_alloc_uninit((long)len, (long)len);
        if (len > 0) memcpy(s->data, line, len);
        s->data[len] = '\0';
        result = blorp_list_append(result, (void*)s);
    }
    free(line);
    fclose(f);
    blorp_list_init_elem_release(result, blorp_elem_release_fn);
    return result;
}


bool blorp_append_file(const blorp_String* path, const blorp_String* content) {
    if (!path) return false;

    char* cpath = blorp_cstring_copy_if_valid(path);
    if (!cpath) return false;

    FILE* f = blorp_runtime_fopen_cloexec(cpath, "ab");
    free(cpath);

    if (!f) return false;

    if (content && content->len > 0) {
        size_t n = fwrite(content->data, 1, (size_t)content->len, f);
        if (n != (size_t)content->len) {
            fclose(f);
            return false;
        }
    }
    return fclose(f) == 0;
}

blorp_Result* blorp_for_each_line(const blorp_String* path, blorp_Closure* callback) {
    if (!path) return blorp_result_err_cstr("File not found: (null)");

    char* cpath = blorp_cstring_copy_if_valid(path);
    if (!cpath) return blorp_result_err_cstr("for_each_line: string contains embedded NUL");

    FILE* f = blorp_runtime_fopen_cloexec(cpath, "rb");
    if (!f) {
        char errbuf[512];
        snprintf(errbuf, sizeof(errbuf), "File not found: %s", cpath);
        free(cpath);
        return blorp_result_err_owned(
            (void*)blorp_string_from_buf(errbuf, strlen(errbuf))
        );
    }
    free(cpath);

    char* line = NULL;
    size_t cap = 0;
    ssize_t len;
    long line_num = 1;
    while ((len = getline(&line, &cap, f)) != -1) {
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            len--;
        }
        blorp_String* s = blorp_string_alloc_uninit((long)len, (long)len);
        if (len > 0) memcpy(s->data, line, len);
        s->data[len] = '\0';
        blorp_call2(callback, (void*)(long)line_num, (void*)s);
        blorp_release(s);
        line_num++;
    }
    bool read_failed = ferror(f) != 0;
    free(line);
    int close_status = fclose(f);
    if (read_failed) {
        return blorp_result_err_cstr("for_each_line: read failed");
    }
    if (close_status != 0) {
        return blorp_result_err_cstr("for_each_line: close failed");
    }
    return blorp_result_ok(NULL);
}

blorp_Result* blorp_for_each_chunk(const blorp_String* path, long chunk_size, blorp_Closure* callback) {
    if (!path) return blorp_result_err_cstr("File not found: (null)");
    if (chunk_size <= 0) chunk_size = 4096;

    char* cpath = blorp_cstring_copy_if_valid(path);
    if (!cpath) return blorp_result_err_cstr("for_each_chunk: string contains embedded NUL");

    int fd = open(cpath, O_RDONLY | O_CLOEXEC);
    if (fd < 0) {
        char errbuf[512];
        snprintf(errbuf, sizeof(errbuf), "File not found: %s", cpath);
        free(cpath);
        return blorp_result_err_owned(
            (void*)blorp_string_from_buf(errbuf, strlen(errbuf))
        );
    }
    free(cpath);

    char* buf = (char*)blorp_malloc_checked(chunk_size);
    while (true) {
        ssize_t nread = read(fd, buf, (size_t)chunk_size);
        if (nread < 0 && errno == EINTR) continue;
        if (nread < 0) {
            free(buf);
            close(fd);
            return blorp_result_err_cstr("for_each_chunk: read failed");
        }
        if (nread == 0) break;
        blorp_String* s = blorp_string_alloc_uninit((long)nread, (long)nread);
        memcpy(s->data, buf, (size_t)nread);
        s->data[nread] = '\0';
        blorp_call1(callback, (void*)s);
        blorp_release(s);
    }
    free(buf);
    if (close(fd) != 0) {
        return blorp_result_err_cstr("for_each_chunk: close failed");
    }
    return blorp_result_ok(NULL);
}

bool blorp_file_exists(const blorp_String* path) {
    if (!path) return false;

    char* cpath = blorp_cstring_copy_if_valid(path);
    if (!cpath) return false;

    FILE* f = blorp_runtime_fopen_cloexec(cpath, "r");
    free(cpath);

    if (f) {
        fclose(f);
        return true;
    }
    return false;
}

static blorp_FileErrorKind blorp_file_error_kind_from_errno(int errnum) {
    switch (errnum) {
        case ENOENT:
            return BLORP_FILE_ERROR_NOT_FOUND;
#ifdef ENOTDIR
        case ENOTDIR:
            return BLORP_FILE_ERROR_INVALID_INPUT;
#endif
        case EACCES:
        case EPERM:
            return BLORP_FILE_ERROR_PERMISSION_DENIED;
        case EEXIST:
            return BLORP_FILE_ERROR_ALREADY_EXISTS;
        case EINTR:
            return BLORP_FILE_ERROR_INTERRUPTED;
#ifdef ETIMEDOUT
        case ETIMEDOUT:
            return BLORP_FILE_ERROR_TIMED_OUT;
#endif
        case EINVAL:
            return BLORP_FILE_ERROR_INVALID_INPUT;
#ifdef ENOTSUP
        case ENOTSUP:
            return BLORP_FILE_ERROR_UNSUPPORTED;
#endif
#if defined(EOPNOTSUPP) && (!defined(ENOTSUP) || EOPNOTSUPP != ENOTSUP)
        case EOPNOTSUPP:
            return BLORP_FILE_ERROR_UNSUPPORTED;
#endif
#ifdef ESPIPE
        case ESPIPE:
            return BLORP_FILE_ERROR_UNSUPPORTED;
#endif
        default:
            return BLORP_FILE_ERROR_OTHER;
    }
}

