static blorp_String* blorp_file_open_errno_detail(
    const blorp_String* path,
    blorp_FileErrorKind kind,
    int errnum
) {
    switch (kind) {
        case BLORP_FILE_ERROR_NOT_FOUND:
        case BLORP_FILE_ERROR_PERMISSION_DENIED:
        case BLORP_FILE_ERROR_ALREADY_EXISTS:
            return (blorp_String*)blorp_retain((void*)path);
        default: {
            const char* message = strerror(errnum);
            return blorp_string_from_buf(message, (long)strlen(message));
        }
    }
}

static blorp_String* blorp_file_operation_errno_detail(
    const char* operation,
    int errnum
) {
    char buf[256];
    const char* message = strerror(errnum);
    snprintf(buf, sizeof(buf), "%s: %s", operation, message);
    return blorp_string_from_buf(buf, (long)strlen(buf));
}

static char* blorp_file_copy_path_for_open(
    const blorp_String* path,
    blorp_FileErrorKind* error_kind,
    blorp_String** error_detail
) {
    if (!path) {
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create("null path");
        return NULL;
    }
    if (path->len <= 0) {
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create("empty path");
        return NULL;
    }
    if (memchr(path->data, '\0', (size_t)path->len) != NULL) {
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create("path contains NUL byte");
        return NULL;
    }

    char* cpath = (char*)blorp_malloc_checked((size_t)path->len + 1);
    memcpy(cpath, path->data, (size_t)path->len);
    cpath[path->len] = '\0';
    return cpath;
}

static int blorp_file_open_fd(
    const blorp_String* path,
    int flags,
    int mode,
    blorp_FileErrorKind* error_kind,
    blorp_String** error_detail
) {
    *error_kind = BLORP_FILE_ERROR_NONE;
    *error_detail = NULL;
    char* cpath = blorp_file_copy_path_for_open(path, error_kind, error_detail);
    if (!cpath) return -1;

#ifdef O_CLOEXEC
    flags |= O_CLOEXEC;
    int fd = open(cpath, flags, mode);
#else
    int lock_status = pthread_mutex_lock(&__process_spawn_mutex);
    if (lock_status != 0) {
        free(cpath);
        *error_kind = BLORP_FILE_ERROR_OTHER;
        *error_detail = blorp_file_operation_errno_detail(
            "lock file open",
            lock_status
        );
        return -1;
    }
    int fd = open(cpath, flags, mode);
    if (fd >= 0 && blorp_runtime_set_cloexec(fd) != 0) {
        int saved_errno = errno;
        close(fd);
        fd = -1;
        errno = saved_errno;
    }
    pthread_mutex_unlock(&__process_spawn_mutex);
#endif
    if (fd < 0) {
        int errnum = errno;
        free(cpath);
        *error_kind = blorp_file_error_kind_from_errno(errnum);
        *error_detail =
            blorp_file_open_errno_detail(path, *error_kind, errnum);
        return -1;
    }
    free(cpath);

    return fd;
}

static blorp_FileStringResult blorp_file_read_text_fd(int fd) {
    if (fd < 0) {
        return blorp_file_string_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_text: closed file handle"));
    }

    long cap = 4096;
    long len = 0;
    char* buf = (char*)blorp_malloc_checked((size_t)cap);

    while (true) {
        if (len == cap) {
            long next_cap = cap > (LONG_MAX / 2) ? LONG_MAX : cap * 2;
            if (next_cap <= cap) {
                free(buf);
                return blorp_file_string_error(BLORP_FILE_ERROR_UNSUPPORTED,
                    blorp_string_create("read_text: file too large"));
            }
            char* new_buf = (char*)realloc(buf, (size_t)next_cap);
            if (!new_buf) {
                free(buf);
                fprintf(stderr,
                    "blorp: out of memory (realloc %ld bytes)\n",
                    next_cap);
                exit(1);
            }
            buf = new_buf;
            cap = next_cap;
        }

        ssize_t n = read(fd, buf + len, (size_t)(cap - len));
        if (n > 0) {
            len += (long)n;
            continue;
        }
        if (n == 0) break;
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("read_text", errnum);
        free(buf);
        return blorp_file_string_error(kind, detail);
    }

    blorp_String* text = blorp_string_from_buf(buf, len);
    free(buf);
    return blorp_file_string_ok(text);
}

static blorp_FileBytesResult blorp_file_read_bytes_fd(int fd) {
    if (fd < 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_bytes: closed file handle"));
    }

    long cap = 4096;
    long len = 0;
    unsigned char* buf = (unsigned char*)blorp_malloc_checked((size_t)cap);

    while (true) {
        if (len == cap) {
            long next_cap = cap > (LONG_MAX / 2) ? LONG_MAX : cap * 2;
            if (next_cap <= cap) {
                free(buf);
                return blorp_file_bytes_error(BLORP_FILE_ERROR_UNSUPPORTED,
                    blorp_string_create("read_bytes: file too large"));
            }
            unsigned char* new_buf =
                (unsigned char*)realloc(buf, (size_t)next_cap);
            if (!new_buf) {
                free(buf);
                fprintf(stderr,
                    "blorp: out of memory (realloc %ld bytes)\n",
                    next_cap);
                exit(1);
            }
            buf = new_buf;
            cap = next_cap;
        }

        ssize_t n = read(fd, buf + len, (size_t)(cap - len));
        if (n > 0) {
            len += (long)n;
            continue;
        }
        if (n == 0) break;
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("read_bytes", errnum);
        free(buf);
        return blorp_file_bytes_error(kind, detail);
    }

    blorp_Bytes* bytes = blorp_bytes_new(len);
    if (len > 0) memcpy(bytes->data, buf, (size_t)len);
    free(buf);
    return blorp_file_bytes_ok(bytes);
}

static blorp_FileBytesResult blorp_file_read_chunk_fd(int fd, long max_bytes) {
    if (fd < 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_chunk: closed file handle"));
    }
    if (max_bytes <= 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_chunk: max_bytes must be positive"));
    }

    blorp_Bytes* bytes = blorp_bytes_new(max_bytes);
    while (true) {
        ssize_t n = read(fd, bytes->data, (size_t)max_bytes);
        if (n >= 0) {
            bytes->len = (long)n;
            return blorp_file_bytes_ok(bytes);
        }
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("read_chunk", errnum);
        blorp_release(bytes);
        return blorp_file_bytes_error(kind, detail);
    }
}

static blorp_FileBytesResult blorp_file_read_chunk_at_fd(
    int fd,
    long offset,
    long max_bytes
) {
    if (fd < 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_chunk_at: closed file handle"));
    }
    if (offset < 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_chunk_at: offset must be non-negative"));
    }
    if (max_bytes <= 0) {
        return blorp_file_bytes_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("read_chunk_at: max_bytes must be positive"));
    }

    blorp_Bytes* bytes = blorp_bytes_new(max_bytes);
    while (true) {
        ssize_t n = pread(fd, bytes->data, (size_t)max_bytes, (off_t)offset);
        if (n >= 0) {
            bytes->len = (long)n;
            return blorp_file_bytes_ok(bytes);
        }
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("read_chunk_at", errnum);
        blorp_release(bytes);
        return blorp_file_bytes_error(kind, detail);
    }
}

static blorp_FileIntResult blorp_file_size_fd(int fd) {
    if (fd < 0) {
        return blorp_file_int_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("size: closed file handle"));
    }

    struct stat st;
    while (true) {
        if (fstat(fd, &st) == 0) return blorp_file_int_ok((long)st.st_size);
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("size", errnum);
        return blorp_file_int_error(kind, detail);
    }
}

static blorp_FileIntResult blorp_file_count_lines_fd(int fd) {
    if (fd < 0) {
        return blorp_file_int_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("count_lines: closed file handle"));
    }

    unsigned char* buf =
        (unsigned char*)blorp_malloc_checked(BLORP_FILE_DEFAULT_CHUNK_SIZE);
    long count = 0;
    bool saw_any = false;
    bool last_was_newline = false;
    long cancel_check = 0;

    while (true) {
        blorp_stream_cancellation_checkpoint(&cancel_check);
        ssize_t n = read(fd, buf, BLORP_FILE_DEFAULT_CHUNK_SIZE);
        if (n > 0) {
            saw_any = true;
            for (ssize_t i = 0; i < n; i++) {
                if (buf[i] == '\n') count++;
            }
            last_was_newline = buf[n - 1] == '\n';
            continue;
        }
        if (n == 0) break;
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("count_lines", errnum);
        free(buf);
        return blorp_file_int_error(kind, detail);
    }

    free(buf);
    if (saw_any && !last_was_newline) count++;
    return blorp_file_int_ok(count);
}

static blorp_FileVoidResult blorp_file_write_text_fd(
    int fd,
    const blorp_String* text
) {
    if (fd < 0) {
        return blorp_file_void_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("write_text: closed file handle"));
    }
    if (!text) {
        return blorp_file_void_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("write_text: null text"));
    }

    const char* data = text->data;
    long remaining = text->len;
    while (remaining > 0) {
        size_t chunk =
            remaining > 1048576L ? (size_t)1048576 : (size_t)remaining;
        ssize_t n = write(fd, data, chunk);
        if (n > 0) {
            data += n;
            remaining -= (long)n;
            continue;
        }
        if (n == 0) {
            return blorp_file_void_error(BLORP_FILE_ERROR_UNSUPPORTED,
                blorp_string_create("write_text: write returned 0"));
        }
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("write_text", errnum);
        return blorp_file_void_error(kind, detail);
    }

    return blorp_file_void_ok();
}

static blorp_FileVoidResult blorp_file_write_bytes_fd(
    int fd,
    const blorp_Bytes* bytes
) {
    if (fd < 0) {
        return blorp_file_void_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("write_bytes: closed file handle"));
    }
    if (!bytes) {
        return blorp_file_void_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("write_bytes: null bytes"));
    }

    const unsigned char* data = bytes->data;
    long remaining = bytes->len;
    while (remaining > 0) {
        size_t chunk =
            remaining > 1048576L ? (size_t)1048576 : (size_t)remaining;
        ssize_t n = write(fd, data, chunk);
        if (n > 0) {
            data += n;
            remaining -= (long)n;
            continue;
        }
        if (n == 0) {
            return blorp_file_void_error(BLORP_FILE_ERROR_UNSUPPORTED,
                blorp_string_create("write_bytes: write returned 0"));
        }
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("write_bytes", errnum);
        return blorp_file_void_error(kind, detail);
    }

    return blorp_file_void_ok();
}

static blorp_FileIntResult blorp_file_write_chunk_fd(
    int fd,
    const blorp_Bytes* bytes
) {
    if (fd < 0) {
        return blorp_file_int_error(BLORP_FILE_ERROR_INVALID_INPUT,
            blorp_string_create("write_chunk: closed file handle"));
    }
    if (!bytes || bytes->len <= 0) return blorp_file_int_ok(0);

    while (true) {
        ssize_t n = write(fd, bytes->data, (size_t)bytes->len);
        if (n >= 0) return blorp_file_int_ok((long)n);
        if (errno == EINTR) continue;

        int errnum = errno;
        blorp_FileErrorKind kind = blorp_file_error_kind_from_errno(errnum);
        blorp_String* detail =
            blorp_file_operation_errno_detail("write_chunk", errnum);
        return blorp_file_int_error(kind, detail);
    }
}

static char* blorp_temporary_template_from_c(
    const char* parent,
    const char* prefix
) {
    size_t parent_len = strlen(parent);
    size_t prefix_len = strlen(prefix);
    bool needs_separator = parent_len == 0 || parent[parent_len - 1] != '/';
    size_t len = blorp_checked_add(parent_len, needs_separator ? 1 : 0);
    len = blorp_checked_add(len, prefix_len);
    len = blorp_checked_add(len, 6);

    char* result = (char*)blorp_malloc_checked(blorp_checked_add(len, 1));
    size_t offset = 0;
    memcpy(result + offset, parent, parent_len);
    offset += parent_len;
    if (needs_separator) result[offset++] = '/';
    memcpy(result + offset, prefix, prefix_len);
    offset += prefix_len;
    memcpy(result + offset, "XXXXXX", 6);
    result[len] = '\0';
    return result;
}

static char* blorp_temporary_template(
    const blorp_String* parent,
    const blorp_String* prefix,
    blorp_FileErrorKind* error_kind,
    blorp_String** error_detail
) {
    char* parent_path =
        blorp_file_copy_path_for_open(parent, error_kind, error_detail);
    if (!parent_path) return NULL;

    if (!prefix || prefix->len <= 0) {
        free(parent_path);
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create(
            "temporary path prefix must be non-empty");
        return NULL;
    }
    if (
        memchr(prefix->data, '\0', (size_t)prefix->len) != NULL ||
        memchr(prefix->data, '/', (size_t)prefix->len) != NULL
    ) {
        free(parent_path);
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create(
            "temporary path prefix must be a filename prefix");
        return NULL;
    }

    char* prefix_text = blorp_cstring_copy_if_valid(prefix);
    if (!prefix_text) {
        free(parent_path);
        *error_kind = BLORP_FILE_ERROR_INVALID_INPUT;
        *error_detail = blorp_string_create("invalid temporary path prefix");
        return NULL;
    }

    char* result = blorp_temporary_template_from_c(parent_path, prefix_text);
    free(prefix_text);
    free(parent_path);
    return result;
}

blorp_FileOpenWriterResult blorp_temporary_file_open_raw(
    const blorp_String* parent,
    const blorp_String* prefix
) {
    blorp_FileErrorKind error_kind = BLORP_FILE_ERROR_NONE;
    blorp_String* error_detail = NULL;
    char* path =
        blorp_temporary_template(parent, prefix, &error_kind, &error_detail);
    if (!path) return blorp_file_open_writer_error(error_kind, error_detail);

    int fd = blorp_runtime_mkstemp_cloexec(path);
    if (fd < 0) {
        int errnum = errno;
        free(path);
        error_kind = blorp_file_error_kind_from_errno(errnum);
        error_detail = blorp_file_open_errno_detail(parent, error_kind, errnum);
        return blorp_file_open_writer_error(error_kind, error_detail);
    }
    blorp_FileWriter* file =
        (blorp_FileWriter*)blorp_malloc_checked(sizeof(blorp_FileWriter));
    file->fd = fd;
    file->path = path;
    file->remove_on_close = true;
    return (blorp_FileOpenWriterResult){
        .handle = file,
        .error_kind = BLORP_FILE_ERROR_NONE,
        .detail = NULL
    };
}

blorp_DirectoryOpenResult blorp_temporary_directory_open_raw(
    const blorp_String* parent,
    const blorp_String* prefix
) {
    blorp_FileErrorKind error_kind = BLORP_FILE_ERROR_NONE;
    blorp_String* error_detail = NULL;
    char* path =
        blorp_temporary_template(parent, prefix, &error_kind, &error_detail);
    if (!path) {
        return blorp_dir_open_error(error_kind, error_detail);
    }

    if (!mkdtemp(path)) {
        int errnum = errno;
        free(path);
        error_kind = blorp_file_error_kind_from_errno(errnum);
        error_detail = blorp_file_open_errno_detail(parent, error_kind, errnum);
        return blorp_dir_open_error(error_kind, error_detail);
    }

    DIR* raw_dir = blorp_runtime_opendir_no_follow_cloexec(path);
    if (!raw_dir) {
        int errnum = errno;
        rmdir(path);
        free(path);
        error_kind = blorp_file_error_kind_from_errno(errnum);
        error_detail = blorp_file_open_errno_detail(parent, error_kind, errnum);
        return blorp_dir_open_error(error_kind, error_detail);
    }

    blorp_Directory* directory =
        (blorp_Directory*)blorp_malloc_checked(sizeof(blorp_Directory));
    directory->dir = raw_dir;
    directory->path = path;
    directory->remove_on_close = true;
    return (blorp_DirectoryOpenResult){
        .handle = directory,
        .error_kind = BLORP_FILE_ERROR_NONE,
        .detail = NULL
    };
}

